import dev.hua.ptcglive.engine.MatchSession;
import dev.hua.ptcglive.engine.ServerMatch;
import dev.hua.ptcglive.engine.ServerRandom;
import dev.hua.ptcglive.engine.field.AbilityDefinition;
import dev.hua.ptcglive.engine.field.AbilityEffect;
import dev.hua.ptcglive.engine.field.PokemonProfile;
import dev.hua.ptcglive.rules.*;
import java.util.*;

/** Own-field Ability target choices are generated by the server and revalidated before the once-per-turn mark. */
public final class AbilityHealTargetTest {
    private static final UUID A = new UUID(0, 6301), B = new UUID(0, 6302);
    public static void main(String[] args) {
        ServerMatch match = fixture();
        reachTurn(match, A);
        UUID source = match.activePokemonView(A).pokemonId();
        UUID target = match.benchPokemonView(A).getFirst().pokemonId();
        UUID opponent = match.activePokemonView(B).pokemonId();
        match.placeDamageCountersByEffect(A, A, target, 3);
        rejects(() -> match.useAbility(A, source, "heal", null));
        rejects(() -> match.useAbility(A, source, "heal", opponent));
        if (!match.canUseAbility(A, source, "heal", target))
            throw new AssertionError("服务器没有允许受伤的己方公开场上目标使用回复特性");
        MatchSession session = MatchSession.multiplayer(match, A, B);
        MatchSession.Snapshot snapshot = session.view(A, A);
        int option = snapshot.options().stream().filter(candidate -> candidate.labelZh().contains("回复特性")
            && candidate.labelZh().contains("备战区")).mapToInt(MatchSession.Option::index).findFirst()
            .orElseThrow(() -> new AssertionError("会话没有生成服务器授权的己方备战目标特性操作"));
        session.submit(A, A, snapshot.revision(), option);
        if (match.activePokemonView(A).damage() != 0 || match.benchPokemonView(A).getFirst().damage() != 10)
            throw new AssertionError("回复特性没有只在服务器上回复指定的己方目标");
        if (match.canUseAbility(A, source, "heal", target))
            throw new AssertionError("目标特性没有计入来源场上实例的一回合一次限制");
        System.out.println("AbilityHealTargetTest passed: own-field Ability targets are server-generated, private-safe and once-per-turn");
    }
    private static void reachTurn(ServerMatch match, UUID player) {
        while (!match.currentPlayer().equals(player)) match.endTurn(match.currentPlayer());
    }
    private static ServerMatch fixture() {
        var definitions = new CardDatabase(List.of(definition("healer"), definition("target")));
        var heal = new AbilityDefinition("heal", "回复特性", new AbilityEffect(AbilityEffect.Opcode.HEAL_OWN_POKEMON, 20),
            EffectSupport.SUPPORTED, null);
        var combat = new CombatCatalog(Map.of(
            "healer", new PokemonProfile(120, 0, null, null, 0, null, 0, 1, List.of(), List.of(heal)),
            "target", new PokemonProfile(120, 0, null, null, 0, null, 0, 1, List.of())), Map.of());
        var match = new ServerMatch(A, B, deck(A, "healer"), deck(B, "target"), MatchRulesRegressionTest.RULE,
            definitions, combat, new ServerRandom(6303));
        OpeningTestSupport.complete(match, A, B, 1);
        return match;
    }
    private static CardDefinition definition(String id) {
        return new CardDefinition(id, id, CardCategory.POKEMON, TrainerCategory.NONE, "H", Set.of("international"), true,
            false, 60, Map.of(), EffectSupport.SUPPORTED, null);
    }
    private static List<CardInstance> deck(UUID owner, String definitionId) {
        var cards = new ArrayList<CardInstance>();
        for (int i = 0; i < 60; i++) cards.add(new CardInstance(UUID.randomUUID(), owner, definitionId));
        return cards;
    }
    private static void rejects(Runnable action) {
        try { action.run(); } catch (IllegalArgumentException | IllegalStateException expected) { return; }
        throw new AssertionError("服务端错误接受了无效的特性目标");
    }
}
